/* Licensed anatomical reference mesh; no inferred personal body shape. */
let disposeBody3D=()=>{};
const segmentsBefore3D=segmentPanel;
segmentPanel=m=>{const detailed=m.segments?.length?m:bodyRecords().find(r=>r.segments?.length)||m;return `<section class="card body-3d-card"><div class="card-head"><div><h2>جسمك: استكشاف ثلاثي الأبعاد</h2><p class="sub">نموذج بشري مرجعي بتفاصيل الوجه واليدين والمفاصل. الأرقام من ${esc(reportDevice(detailed))} · ${pretty(detailed.date)}.${detailed.id!==m.id?' تفاصيل من فحص أقدم لأن القياس المختار لا يشمل المناطق.':''}</p></div><span class="chip">3D تفاعلي</span></div><div class="body-3d-grid"><div class="body-3d-stage"><canvas id="body3dCanvas" aria-label="نموذج بشري مرجعي؛ اسحب للتدوير واستخدم أزرار المناطق لقراءة القياسات" role="img"></canvas><p id="body3dStatus" class="sub">اسحب للتدوير · اضغط منطقة لقراءة أرقامها</p><div class="quick-buttons no-print"><button class="button secondary" data-body3d="reset">أمام</button><button class="button secondary" data-body3d="back">خلف</button><button class="button secondary" data-body3d="plus" aria-label="تكبير المجسم">+</button><button class="button secondary" data-body3d="minus" aria-label="تصغير المجسم">−</button></div></div><div><div class="quick-buttons" id="body3dRegions">${['الجذع','الذراع الأيمن','الذراع الأيسر','الساق اليمنى','الساق اليسرى'].map((name,i)=>`<button class="button secondary" data-body-region="${i}" aria-pressed="false">${name}</button>`).join('')}</div><div id="body3dDetail" class="body-region-detail" aria-live="polite"></div><p class="notice">اللون يحدد المنطقة المختارة فقط؛ لا يشخّص زيادة الدهون. حجم المجسم لا يمثل مقاسات جسمك ولا يتغير لإظهار شكل متوقع بعد التنشيف.</p></div></div></section>`+segmentsBefore3D(m);};
function initBody3D(){disposeBody3D();const canvas=document.querySelector('#body3dCanvas');if(!canvas)return;const chosen=currentBodyReport(),report=chosen.segments?.length?chosen:bodyRecords().find(r=>r.segments?.length)||chosen,names=['الجذع','الذراع الأيمن','الذراع الأيسر','الساق اليمنى','الساق اليسرى'];let selectedRegion=0;
 function showRegion(i){selectedRegion=i;const name=names[i],part=report.segments?.find(s=>s.name===name);document.querySelector('#body3dDetail').innerHTML=`<h3>${name}</h3>${part?`<div class="body-metrics">${bodyMetric(report.muscleType==='total'?'عضلات المنطقة':'كتلة خالية من الدهون',part.lean,'كجم','حسب تعريف الجهاز')}${bodyMetric('دهون المنطقة',part.fat,'كجم','تقدير الجهاز')}</div>${part.leanPercent!=null?`<p>الكتلة الخالية من الدهون بالنسبة لمرجع التقرير: ${fmt(part.leanPercent)}٪.</p>`:''}${part.fatPercent!=null?`<p>دهون المنطقة بالنسبة لمرجع التقرير: ${fmt(part.fatPercent)}٪، وليست نسبة الدهون داخل المنطقة.</p>`:''}`:'<p>هذا القياس لا يتضمن أرقام هذه المنطقة. اختر فحص InBody أو Boditrax المفصل من القائمة بالأعلى.</p>'}`;document.querySelectorAll('[data-body-region]').forEach(b=>{const active=Number(b.dataset.bodyRegion)===i;b.setAttribute('aria-pressed',String(active));b.classList.toggle('secondary',!active)});}
 showRegion(0);
 let gl;try{gl=canvas.getContext('webgl',{antialias:true,alpha:true,preserveDrawingBuffer:true})}catch{}
 const regionButtons=[...document.querySelectorAll('[data-body-region]')];let draw=()=>{};const handlers=[];for(const b of regionButtons){const h=()=>{showRegion(Number(b.dataset.bodyRegion));draw()};b.addEventListener('click',h);handlers.push(()=>b.removeEventListener('click',h))}
 if(!gl){document.querySelector('#body3dStatus').textContent='العرض ثلاثي الأبعاد غير مدعوم في هذا المتصفح. استخدم أزرار المناطق لعرض القياسات.';canvas.hidden=true;disposeBody3D=()=>handlers.forEach(f=>f());return;}
 const vertex=`attribute vec3 p;attribute vec3 n;uniform float yaw;uniform float pitch;uniform float aspect;uniform float zoom;varying vec3 normal;void main(){mat3 ry=mat3(cos(yaw),0.,-sin(yaw),0.,1.,0.,sin(yaw),0.,cos(yaw));mat3 rx=mat3(1.,0.,0.,0.,cos(pitch),sin(pitch),0.,-sin(pitch),cos(pitch));vec3 v=rx*ry*p;normal=rx*ry*n;float z=4.7-v.z;gl_Position=vec4(v.x*zoom/aspect,v.y*zoom,(z-2.0)/3.0,z);}`;
 const fragment=`precision mediump float;varying vec3 normal;uniform vec3 color;uniform float picking;void main(){vec3 N=normalize(normal);float light=.32+.62*max(0.,dot(N,normalize(vec3(-.6,.8,1.))))+.12*max(0.,dot(N,normalize(vec3(.8,.2,-1.))));float shine=pow(max(0.,dot(N,normalize(vec3(-.3,.4,1.)))),32.)*.14;gl_FragColor=vec4(mix(color*light+vec3(shine),color,picking),1.);}`;
 function shader(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error('shader');return s}
 let program,vs,fs;try{vs=shader(gl.VERTEX_SHADER,vertex);fs=shader(gl.FRAGMENT_SHADER,fragment);program=gl.createProgram();gl.attachShader(program,vs);gl.attachShader(program,fs);gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error('link')}catch{document.querySelector('#body3dStatus').textContent='تعذر تشغيل المجسم. القياسات متاحة من أزرار المناطق.';disposeBody3D=()=>handlers.forEach(f=>f());return}
 gl.useProgram(program);gl.enable(gl.DEPTH_TEST);const loc={};for(const k of ['yaw','pitch','aspect','zoom','color','picking'])loc[k]=gl.getUniformLocation(program,k);const pLoc=gl.getAttribLocation(program,'p'),nLoc=gl.getAttribLocation(program,'n');
 function decode16(encoded,signed=false){const bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));return signed?new Int16Array(bytes.buffer):new Uint16Array(bytes.buffer)}
 const model=window.fitnessBodyModel,raw=decode16(model.vertices,true),vertices=Float32Array.from(raw,x=>x/model.scale),normals=new Float32Array(vertices.length),parts=model.parts.map(p=>({...p,indices:decode16(p.faces)}));
 for(const part of parts)for(let i=0;i<part.indices.length;i+=3){const a=part.indices[i]*3,b=part.indices[i+1]*3,c=part.indices[i+2]*3,u=[vertices[b]-vertices[a],vertices[b+1]-vertices[a+1],vertices[b+2]-vertices[a+2]],v=[vertices[c]-vertices[a],vertices[c+1]-vertices[a+1],vertices[c+2]-vertices[a+2]],n=[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]];for(const j of [a,b,c])for(let k=0;k<3;k++)normals[j+k]+=n[k]}
 for(let i=0;i<normals.length;i+=3){const len=Math.hypot(normals[i],normals[i+1],normals[i+2])||1;for(let j=0;j<3;j++)normals[i+j]/=len}
 const meshes=parts.map(part=>{const p=[],n=[];for(const i of part.indices){p.push(vertices[i*3],vertices[i*3+1],vertices[i*3+2]);n.push(normals[i*3],normals[i*3+1],normals[i*3+2])}const pos=gl.createBuffer(),normal=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,pos);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(p),gl.STATIC_DRAW);gl.bindBuffer(gl.ARRAY_BUFFER,normal);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(n),gl.STATIC_DRAW);return {pos,normal,count:p.length/3,region:part.region}});
 let yaw=0,pitch=0,zoom=2.35,disposed=false;
 draw=(picking=false)=>{if(disposed||!canvas.isConnected)return;const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2),w=Math.max(1,Math.floor(rect.width*dpr)),h=Math.max(1,Math.floor(rect.height*dpr));if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}gl.viewport(0,0,w,h);gl.clearColor(0,0,0,picking?1:0);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.uniform1f(loc.yaw,yaw);gl.uniform1f(loc.pitch,pitch);gl.uniform1f(loc.aspect,w/h);gl.uniform1f(loc.zoom,zoom);gl.uniform1f(loc.picking,picking?1:0);if(picking)gl.disable(gl.DITHER);else gl.enable(gl.DITHER);for(const m of meshes){gl.bindBuffer(gl.ARRAY_BUFFER,m.pos);gl.enableVertexAttribArray(pLoc);gl.vertexAttribPointer(pLoc,3,gl.FLOAT,false,0,0);gl.bindBuffer(gl.ARRAY_BUFFER,m.normal);gl.enableVertexAttribArray(nLoc);gl.vertexAttribPointer(nLoc,3,gl.FLOAT,false,0,0);gl.uniform3fv(loc.color,picking?[(m.region+2)/255,0,0]:m.region===selectedRegion?[.26,.78,.71]:[.66,.73,.76]);gl.drawArrays(gl.TRIANGLES,0,m.count)}};
 let start=null;const down=e=>{start={x:e.clientX,y:e.clientY,yaw,pitch,moved:false};canvas.setPointerCapture(e.pointerId)},move=e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.hypot(dx,dy)>5)start.moved=true;yaw=start.yaw+dx*.012;pitch=Math.max(-.6,Math.min(.6,start.pitch+dy*.008));draw()},up=e=>{if(start&&!start.moved){draw(true);const r=canvas.getBoundingClientRect(),pixel=new Uint8Array(4);gl.readPixels(Math.floor((e.clientX-r.left)*canvas.width/r.width),Math.floor((r.bottom-e.clientY)*canvas.height/r.height),1,1,gl.RGBA,gl.UNSIGNED_BYTE,pixel);const i=pixel[0]-2;if(i>=0&&i<5)showRegion(i);draw()}start=null},cancel=()=>{start=null};
 for(const [event,h] of [['pointerdown',down],['pointermove',move],['pointerup',up],['pointercancel',cancel]]){canvas.addEventListener(event,h);handlers.push(()=>canvas.removeEventListener(event,h))}
 for(const b of document.querySelectorAll('[data-body3d]')){const h=()=>{const a=b.dataset.body3d;if(a==='reset'){yaw=0;pitch=0;zoom=2.35}if(a==='back')yaw=Math.PI;if(a==='plus')zoom=Math.min(3.4,zoom+.2);if(a==='minus')zoom=Math.max(1.6,zoom-.2);draw()};b.addEventListener('click',h);handlers.push(()=>b.removeEventListener('click',h))}
 const resize=new ResizeObserver(()=>draw());resize.observe(canvas);draw();disposeBody3D=()=>{disposed=true;resize.disconnect();handlers.forEach(f=>f());for(const m of meshes){gl.deleteBuffer(m.pos);gl.deleteBuffer(m.normal)}gl.deleteProgram(program);gl.deleteShader(vs);gl.deleteShader(fs);gl.getExtension('WEBGL_lose_context')?.loseContext()};
}
const renderBefore3D=render;render=function(){disposeBody3D();disposeBody3D=()=>{};renderBefore3D();if(view==='body')initBody3D()};render();
